// MIT. Shared mechanics for source-owned original Applications adapters.
import { StringDecoder } from 'node:string_decoder';
import { access, realpath } from 'node:fs/promises';
import { constants } from 'node:fs';
import { join } from 'node:path';
import { need, plain, saveJSON, now } from './storage.mjs';

export const APPLICATION_PROVIDER_SCHEMA = 'stellar-forge.runtime-application-provider.v1';
export const applicationField = (name, label, type = 'path', required = false, description = '') =>
  ({ name, label, type, required, description });
export const applicationCommonFields = Object.freeze([
  applicationField('port', 'Local port', 'port', false,
    'Use 0 to let the original application choose an available port.'),
  applicationField('environmentFile', 'Private environment JSON', 'path', false,
    'Optional private file containing environment names and string values. Values stay on this host.'),
]);

/** Original path and argv helpers for adapters moved out of the shared dispatcher. */
export function applicationPreparation(settings, inputPath) {
  const args = [], inputs = [], createDirectories = [];
  return {
    args, inputs, createDirectories,
    async path(name, kind = 'directory', missing = false, privateOnly = false) {
      if (!settings[name]) return;
      const value = await inputPath(settings[name], kind, missing, privateOnly);
      inputs.push(value); return value;
    },
    option(name, value) {
      if (value !== undefined && value !== '') args.push(name, String(value));
    },
  };
}

/** Keep the original common port, private environment and terminal preparation. */
export async function prepareProviderApplication(provider, type, settings, context) {
  const selected = await provider.prepare(type, settings, context);
  need(plain(selected) && Array.isArray(selected.args) &&
    selected.args.every(value => typeof value === 'string') &&
    Array.isArray(selected.inputs) && Array.isArray(selected.createDirectories),
  'APPLICATION_PROVIDER_PREPARATION_INVALID', 'The ' + provider.id + ' provider returned an invalid original command.');
  if (provider.completeCommand === true) {
    need(selected.command === type.command && selected.terminal === type.terminal,
      'APPLICATION_PROVIDER_COMMAND_CHANGED', 'The original provider command differs from its catalog.');
    return selected;
  }
  const args = [...selected.args], inputs = [...selected.inputs];
  let terminalPython;
  if (type.terminal) {
    terminalPython = await realpath(settings.terminalPython ?? '/usr/bin/python3');
    inputs.push(await context.inputPath(terminalPython, 'file'));
    await access(terminalPython, constants.X_OK);
  }
  if (provider.appendPort !== false && settings.port !== undefined && settings.port !== '')
    args.push('--port', String(settings.port));
  if (settings.environmentFile) inputs.push(await context.inputPath(settings.environmentFile, 'file'));
  const environment = await context.applicationEnvironment(settings.environmentFile);
  return { ...selected, command: type.command, args, inputs, terminal: type.terminal,
    ...(type.terminal ? { terminalPython } : {}),
    ...(settings.environmentFile ?
      { environmentFile: settings.environmentFile, environmentSha256: environment.sha256 } : {}) };
}

/** Bind run-specific arguments only when the reviewed original operation is retained. */
export function retainedApplicationArguments(provider, command, requestId) {
  const args = provider.runArguments
    ? provider.runArguments({command:command.command, args:[...command.args], requestId})
    : [...command.args];
  need(Array.isArray(args) && args.every(value => typeof value === 'string'),
    'APPLICATION_PROVIDER_RUN_ARGUMENTS_INVALID',
    'The ' + provider.id + ' provider must return the original managed argument list.');
  return args;
}

export function applicationPrivateUrl(text) {
  try {
    const url = new URL(text);
    if (url.protocol !== 'http:' || !['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname) ||
        Number(url.port || 80) < 1 || Number(url.port || 80) > 65535 ||
        url.username || url.password || text.length > 4096) return null;
    return url.href;
  } catch { return null; }
}

/**
 * A provider synchronously reads original normalized startup lines. It returns a URL,
 * {url, original?, links?, workspaceId?, connectionFile?}, a deferred resolver function, an array of those values, or null.
 * Defer asynchronous source checks so ignored later announcements never run them. Stateful original
 * multi-line readers live in that provider. This one writer retains the first
 * accepted announcement, its original identity and the shared operation ID.
 */
export function observeApplicationStartup(request, directory, readLine, { lineLimit = 16384 } = {}) {
  need(typeof readLine === 'function', 'APPLICATION_PROVIDER_OBSERVER_REQUIRED');
  need(Number.isSafeInteger(lineLimit) && lineLimit >= 1 && lineLimit <= 1024 * 1024,
    'APPLICATION_PROVIDER_LINE_LIMIT_INVALID');
  let buffer = '', seen = false, closed = false, saveError = null, saving = Promise.resolve();
  const decoder = new StringDecoder('utf8');
  function line(value) {
    if (seen || !request.applicationId) return;
    const text = value.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '').trim();
    let result;
    try { result = readLine(text); }
    catch (error) { saveError = error; return; }
    for (const selected of Array.isArray(result) ? result : [result]) {
      if (!selected) continue;
      saving = saving.then(async () => {
        if (seen) return;
        const candidate = typeof selected === 'function' ? await selected() : await selected;
        const startup = typeof candidate === 'string' ? { url: candidate } : candidate;
        const url = startup && applicationPrivateUrl(startup.url);
        if (!url) return;
        seen = true;
        await saveJSON(join(directory, 'application-url.json'), {
          schema: 'stellar-forge.application-url.v1', applicationId: request.applicationId,
          operationId: directory.split('/').at(-1), command: request.command,
          source: 'original-command-stdout', observedAt: now(), url,
          ...(Object.hasOwn(startup, 'links') ? { links: startup.links } : {}),
          ...(Object.hasOwn(startup, 'original') ? { original: startup.original } : {}),
          ...(Object.hasOwn(startup, 'workspaceId') ? { workspaceId: startup.workspaceId } : {}),
          ...(Object.hasOwn(startup, 'connectionFile') ? { connectionFile: startup.connectionFile } : {}),
        });
      }).catch(error => { if (error.code !== 'EEXIST') saveError = error; });
    }
  }
  return {
    write(bytes) {
      if (!request.applicationId || seen || closed) return;
      buffer += decoder.write(bytes);
      const lines = buffer.split(/\r?\n/); buffer = lines.pop();
      for (const text of lines) line(text);
      if (buffer.length > lineLimit) buffer = buffer.slice(-lineLimit);
    },
    async close() {
      if (!closed) { closed = true; buffer += decoder.end(); if (buffer) line(buffer); }
      await saving; if (saveError) throw saveError;
    },
  };
}

// MIT. Private retained records for the original runtime operator workspace.
import { constants } from 'node:fs';
import { open, mkdir, lstat, realpath, rename, readFile, link, unlink } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { spawnSync } from 'node:child_process';

export const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
export const now = () => new Date().toISOString();
export const digest = value => createHash('sha256').update(value).digest('hex');
export const json = value => JSON.stringify(value, null, 2) + '\n';
export const fail = (code, message = code, status = 400) => { throw Object.assign(new Error(message), { code, status }); };
export const need = (value, code, message, status) => { if (!value) fail(code, message, status); };
export function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  return plain(value) ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;
}
export function recordId(value) {
  need(typeof value === 'string' && /^[a-f0-9]{24}$/.test(value), 'RUNTIME_WORKSPACE_RECORD_INVALID');
  return value;
}
export function operationId(value) {
  need(typeof value === 'string' && /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/.test(value),
    'RUNTIME_WORKSPACE_OPERATION_INVALID');
  return value;
}
export function absolute(value) {
  need(typeof value === 'string' && value && value === resolve(value) && !value.includes('\0'),
    'RUNTIME_WORKSPACE_ABSOLUTE_PATH_REQUIRED');
  return value;
}
export async function privateDirectory(value) {
  const path = absolute(value), info = await lstat(path);
  need(info.isDirectory() && !info.isSymbolicLink() && await realpath(path) === path &&
    !(info.mode & 0o077) && (process.getuid === undefined || info.uid === process.getuid()),
  'RUNTIME_WORKSPACE_PRIVATE_DIRECTORY_REQUIRED', 'Use a private real directory owned by the current operator');
  return path;
}
export async function makePrivate(value) {
  const path = absolute(value);
  need(await realpath(dirname(path)) === dirname(path), 'RUNTIME_WORKSPACE_REAL_PARENT_REQUIRED');
  await mkdir(path, { mode: 0o700 });
  return privateDirectory(path);
}
export async function regular(path, maximum = 4 * 1024 * 1024) {
  const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const first = await handle.stat();
    need(first.isFile() && first.size <= maximum, 'RUNTIME_WORKSPACE_FILE_INVALID');
    const bytes = await handle.readFile(), last = await handle.stat();
    need(bytes.length <= maximum && first.size === last.size && first.mtimeMs === last.mtimeMs &&
      first.ctimeMs === last.ctimeMs, 'RUNTIME_WORKSPACE_FILE_CHANGED');
    return bytes;
  } finally { await handle.close(); }
}
export async function readJSON(path, optional = false) {
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(await regular(path))); }
  catch (error) { if (optional && error.code === 'ENOENT') return null; throw error; }
}
export async function saveJSON(path, value, replace = false) {
  const temporary = path + '.pending-' + randomUUID();
  const handle = await open(temporary, 'wx', 0o600);
  try { await handle.writeFile(json(value)); await handle.sync(); }
  finally { await handle.close(); }
  if (replace) await rename(temporary, path);
  else {
    try { await link(temporary, path); }
    finally { await unlink(temporary); }
  }
  const parent = await open(dirname(path), constants.O_RDONLY | constants.O_DIRECTORY);
  try { await parent.sync(); } finally { await parent.close(); }
}
export async function processIdentity(pid = process.pid) {
  try {
    if (!Number.isInteger(pid) || pid <= 0) return null;
    const selfText = await readFile('/proc/self/stat', 'utf8');
    const selfPid = Number(selfText.slice(0, selfText.indexOf(' ')));
    const parse = text => {
      const fields = text.slice(text.lastIndexOf(')') + 2).trim().split(/\s+/);
      return fields[0] === 'Z' ? null : fields[19] ?? null;
    };
    if (pid === process.pid) return parse(selfText);
    if (selfPid === process.pid) return parse(await readFile('/proc/' + pid + '/stat', 'utf8'));
    const selfStatus = await readFile('/proc/self/status', 'utf8');
    const ownIds = selfStatus.match(/^NSpid:\s+(.+)$/m)?.[1].trim().split(/\s+/);
    if (!ownIds) return null;
    const depth = ownIds.length - 1, pending = [selfPid], visited = new Set();
    // Only resolve this process's descendants. A receiving server in a
    // different namespace relies on the original kernel lease and stop file.
    while (pending.length && visited.size < 256) {
      const parent = pending.shift();
      if (visited.has(parent)) continue;
      visited.add(parent);
      let children;
      try { children = (await readFile('/proc/' + parent + '/task/' + parent + '/children', 'utf8')).trim().split(/\s+/).filter(Boolean); }
      catch { continue; }
      for (const child of children) {
        try {
          const status = await readFile('/proc/' + child + '/status', 'utf8');
          const ids = status.match(/^NSpid:\s+(.+)$/m)?.[1].trim().split(/\s+/);
          if (ids && Number(ids[depth]) === pid)
            return parse(await readFile('/proc/' + child + '/stat', 'utf8'));
          pending.push(Number(child));
        } catch {}
      }
    }
    return null;
  } catch { return null; }
}
export async function workerAlive(state) {
  return Number.isInteger(state?.pid) && typeof state?.processStart === 'string' &&
    await processIdentity(state.pid) === state.processStart;
}
export async function operationLease(path) {
  const handle = await open(path, constants.O_RDWR | constants.O_CREAT | constants.O_NOFOLLOW, 0o600);
  try {
    const info = await handle.stat();
    need(info.isFile() && info.nlink === 1 && !(info.mode & 0o077), 'RUNTIME_WORKSPACE_LEASE_INVALID');
    const result = spawnSync('flock', ['--exclusive', '--nonblock', '--conflict-exit-code', '75', '3'],
      { stdio: ['ignore', 'ignore', 'ignore', handle.fd], timeout: 5000 });
    need(!result.error && result.status === 0,
      result.status === 75 ? 'RUNTIME_WORKSPACE_OPERATION_RUNNING' : 'RUNTIME_WORKSPACE_FLOCK_UNAVAILABLE');
    return handle;
  } catch (error) { await handle.close(); throw error; }
}
// The existing kernel lease remains authoritative when a container's mounted
// /proc does not expose its inner PID namespace.
export async function operationRunning(path) {
  let lease;
  try { lease = await operationLease(path); return false; }
  catch (error) { if (error.code === 'RUNTIME_WORKSPACE_OPERATION_RUNNING') return true; throw error; }
  finally { if (lease) await lease.close(); }
}
export async function tailFile(path, maximum = 65536) {
  const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const info = await handle.stat();
    need(info.isFile(), 'RUNTIME_WORKSPACE_LOG_INVALID');
    const start = Math.max(0, info.size - maximum), bytes = Buffer.alloc(Math.min(info.size, maximum));
    const read = await handle.read(bytes, 0, bytes.length, start);
    return { text: bytes.subarray(0, read.bytesRead).toString('utf8'), totalBytes: info.size, offset: start };
  } finally { await handle.close(); }
}

// MIT. Linux flock retained by the gateway's own open file description.
import { spawnSync } from 'node:child_process';
import { constants, openSync, fstatSync, lstatSync, closeSync } from 'node:fs';
import { join } from 'node:path';

export async function acquireStateLease(directory) {
  const path = join(directory, 'lease.lock');
  const fd = openSync(path, constants.O_CREAT | constants.O_RDWR | constants.O_NOFOLLOW, 0o600);
  let closed = false;
  const assertHeld = () => {
    if (closed) throw new Error('FLEET_STATE_LEASE_LOST');
    const stat = fstatSync(fd);
    const named = lstatSync(path);
    if (!stat.isFile() || !named.isFile() || named.isSymbolicLink() ||
        (stat.mode & 0o077) || stat.dev !== named.dev || stat.ino !== named.ino)
      throw new Error('FLEET_PRIVATE_LEASE_REQUIRED');
  };
  try {
    assertHeld();
    // fd3 is a duplicate of OUR open file description, not a second open.
    // Successful helper exit leaves its flock held by the retained parent fd.
    // Parent close/crash releases it; no surviving helper or stale-PID recovery.
    const result = spawnSync('flock', ['--exclusive', '--nonblock', '--conflict-exit-code', '73', '3'],
      { stdio: ['ignore', 'pipe', 'pipe', fd], timeout: 10000 });
    if (result.error) throw Object.assign(new Error(result.error.code === 'ENOENT' ?
      'FLEET_LINUX_FLOCK_REQUIRED' : 'FLEET_STATE_LEASE_FAILED'), { cause: result.error });
    if (result.status !== 0) throw new Error(result.status === 73 ?
      'FLEET_STATE_ALREADY_OWNED' : 'FLEET_STATE_LEASE_FAILED');
    assertHeld();
    return {
      pid: process.pid, assertHeld,
      async close() { if (!closed) { closed = true; closeSync(fd); } },
    };
  } catch (error) { closed = true; closeSync(fd); throw error; }
}

// MIT. Typed source adapter for the original issued buyer expense period.
// No payment, journal, exchange-rate or merchant-report synthesis occurs here.
import {createHash,randomUUID} from 'node:crypto';

export const BUYER_SOURCE_SCHEMA='stellar-forge.buyer-accountant-source.v1';
export const BUYER_HANDOFF_SCHEMA='stellar-forge.buyer-accountant-handoff.v1';
export const BUYER_RETURN_SCHEMA='stellar-forge.buyer-accountant-return.v1';
export const BUYER_RETURN_PACKET_SCHEMA='stellar-forge.buyer-accountant-return-packet.v1';
const HEX=/^[0-9a-f]{64}$/;
const ID=/^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$/;
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const check=(ok,code,message,status=400)=>{if(!ok)throw Object.assign(new Error(message),{code,status});};
export const buyerHash=x=>createHash('sha256').update(x).digest('hex');
export function buyerCanonical(value){
  if(value===null||typeof value==='string'||typeof value==='boolean')return JSON.stringify(value);
  if(typeof value==='number'){check(Number.isFinite(value),'INVALID_BUYER_SOURCE','A retained source has an invalid number.');return JSON.stringify(value);}
  if(Array.isArray(value))return '['+value.map(buyerCanonical).join(',')+']';
  check(object(value),'INVALID_BUYER_SOURCE','Retain JSON-compatible source values.');
  return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+buyerCanonical(value[k])).join(',')+'}';
}
const copy=x=>JSON.parse(buyerCanonical(x));
const seal=x=>({...x,integrity:{sha256:buyerHash(buyerCanonical(x))}});
const text=(x,label,max=2000,empty=false)=>{
  check(typeof x==='string'&&x.length<=max&&(empty||x.trim())&&!/[\u0000-\u001f\u007f]/.test(x),'INVALID_BUYER_SOURCE','Retain '+label+' as exact text.');return x;
};
const ident=(x,label)=>{check(typeof x==='string'&&ID.test(x),'INVALID_BUYER_SOURCE','Retain the original '+label+'.');return x;};
const nativeAmount=(x,label)=>{check(typeof x==='string'&&/^(?:0|[1-9]\d{0,99})$/.test(x),'INVALID_BUYER_SOURCE','Retain '+label+' as an exact nonnegative native-unit string.');return BigInt(x);};
const date=x=>{check(typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x+'T00:00:00Z'))&&new Date(x+'T00:00:00Z').toISOString().slice(0,10)===x,'INVALID_BUYER_SOURCE','Retain the original recognition date.');return x;};
const sourceLineId=(workspace,kind,row)=>buyerHash('stellar-forge.buyer-accountant-line.v1\n'+workspace+'\n'+kind+'\n'+row.coding_id+'\n'+row.line);
const rowId=(handoffId,sourceSha,lineId)=>buyerHash('stellar-forge.buyer-accountant-row.v1\n'+handoffId+'\n'+sourceSha+'\n'+lineId);

export const BUYER_FIELDS=Object.freeze([
  'allocationKind','sourceLineId','item_id','credit_id','source_id','source_name','source_capture','source_kind',
  'request_id','request_digest','recognition_date','network','asset','amount','settled_actual','native_return',
  'native_source_day','native_date_basis','receipt_ref','proof_sha256','packet_id','manifest_sha256',
  'adjustment_id','refund_id','source_reference','order_reference','original_transaction','transaction',
  'transfer_identity','observation_sha256','native_transfer_at','data_context',
  'center_id','center_code','center_name','project','account_code','memo','coding_id','line'
]);
export const BUYER_PROTECTED_COLUMNS=Object.freeze([
  'handoffId','sourceWorkspaceId','sourceCloseId','sourceCloseSequence','sourceContextSha256','sourceReportSha256',
  'rowId','sourceRowSha256',...BUYER_FIELDS,'assetLabel','unitLabel','accountCode','accountName'
]);
export const isBuyerHandoff=x=>x?.schema===BUYER_HANDOFF_SCHEMA;

function amountGroups(rows){
  const groups=new Map();
  for(const row of rows){const key=buyerCanonical([row.network,row.asset]),old=groups.get(key)??{network:row.network,asset:row.asset,amount:0n,lines:0};old.amount+=BigInt(row.amount);old.lines++;groups.set(key,old);}
  return [...groups.values()].map(row=>({...row,amount:row.amount.toString()})).sort((a,b)=>buyerCanonical([a.network,a.asset]).localeCompare(buyerCanonical([b.network,b.asset])));
}
function compareTotals(rows,totals,label){
  check(Array.isArray(totals),'INVALID_BUYER_SOURCE','Retain the original '+label+'.');
  const normalize=x=>x.map(row=>({network:row.network,asset:row.asset,amount:row.amount,lines:row.lines})).sort((a,b)=>buyerCanonical([a.network,a.asset]).localeCompare(buyerCanonical([b.network,b.asset])));
  check(buyerCanonical(amountGroups(rows))===buyerCanonical(normalize(totals)),'BUYER_TOTALS_CHANGED','The issued '+label+' do not match the retained allocation lines.',409);
}

/** Validate a closed, reviewed original period while retaining every source field. */
export function inspectBuyerSource(input){
  const raw=Buffer.from(input);
  check(raw.length>0&&raw.length<=64*1024*1024,'BUYER_SOURCE_SIZE','Choose an original buyer source JSON file up to 64 MiB.');
  let source;try{source=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));}catch{check(false,'INVALID_BUYER_SOURCE','Choose original UTF-8 buyer source JSON.');}
  check(object(source)&&source.schema===BUYER_SOURCE_SCHEMA&&object(source.issued),'BUYER_SOURCE_REQUIRED','Export an issued accountant source from the original buyer expense workspace.');
  ident(source.workspaceId,'buyer workspace identity');
  const close=source.issued;
  check(close.schema==='stellar-forge.buyer-expense-period.v1'&&close.status==='CLOSED'&&close.ready===true&&close.unresolved===0&&object(close.period)&&close.period.state==='CLOSED'&&close.period.latest_close===close.id&&object(close.review)&&close.review.decision==='READY','BUYER_ISSUED_SOURCE_REQUIRED','Use a retained closed edition with its original completed review.');
  ident(close.id,'issued close identity');ident(close.period.id,'buyer period identity');
  check(Number.isSafeInteger(close.sequence)&&close.sequence>0&&HEX.test(close.context_sha256)&&typeof close.created_at==='string'&&Number.isFinite(Date.parse(close.created_at)),'INVALID_BUYER_SOURCE','Retain the issued sequence, time and source context.');
  const start=date(close.period.from_day),end=date(close.period.through_day);
  check(start<=end&&['operational','development'].includes(close.data_context??'operational'),'INVALID_BUYER_SOURCE','Retain the original period scope and data context.');
  check(Array.isArray(close.allocations)&&Array.isArray(close.credit_allocations??[])&&close.allocations.length+(close.credit_allocations??[]).length<=22000,'BUYER_ROW_LIMIT','Retain up to 22,000 issued expense and credit allocation lines.');
  const seen=new Set(),rows=[],economic=new Map();
  for(const [kind,lines]of [['EXPENSE',close.allocations],['CREDIT',close.credit_allocations??[]]]){
    for(const original of lines){
      check(object(original),'INVALID_BUYER_SOURCE','Retain the complete original allocation object.');
      for(const key of ['item_id','coding_id','source_id','source_capture','center_id'])ident(original[key],key);
      if(kind==='CREDIT')ident(original.credit_id,'credit identity');
      check(Number.isSafeInteger(original.line)&&original.line>0,'INVALID_BUYER_SOURCE','Retain the original positive allocation line number.');
      text(original.network,'network',200);text(original.asset,'asset',1000);text(original.center_code,'cost center code',160);text(original.project,'project',2000,true);text(original.account_code,'account code',160,true);
      const amount=nativeAmount(original.amount,'allocation amount'),maximum=nativeAmount(kind==='EXPENSE'?original.settled_actual:original.native_return,'original economic amount');
      check(amount<=maximum,'BUYER_ALLOCATION_CHANGED','An allocation exceeds its original economic amount.',409);
      const economicKey=buyerCanonical([kind,kind==='CREDIT'?original.credit_id:original.item_id]);
      const previous=economic.get(economicKey);
      if(previous)check(previous.network===original.network&&previous.asset===original.asset&&previous.maximum===maximum,
        'BUYER_ECONOMIC_SOURCE_CHANGED','Allocation lines disagree on their original economic amount or denomination.',409);
      const allocated=(previous?.allocated??0n)+amount;
      check(allocated<=maximum,'BUYER_ALLOCATION_CHANGED','The combined allocations exceed their original expense or returned-credit amount.',409);
      economic.set(economicKey,{network:original.network,asset:original.asset,maximum,allocated});
      check(date(original.recognition_date)>=start&&original.recognition_date<=end,'BUYER_DATE_CHANGED','An allocation falls outside the frozen buyer period.',409);
      const identity=sourceLineId(source.workspaceId,kind,original);
      check(!seen.has(identity),'BUYER_LINE_REPEATED','The issued source repeats an allocation identity.',409);seen.add(identity);
      rows.push({kind,sourceLineId:identity,original:copy(original)});
    }
  }
  compareTotals(close.allocations,close.totals,'expense totals');
  if(close.credit_totals)compareTotals(close.credit_allocations??[],close.credit_totals,'credit totals');
  if(close.net_totals)compareTotals([...close.allocations,...(close.credit_allocations??[]).map(row=>({...row,amount:(-BigInt(row.amount)).toString()}))],close.net_totals,'net totals');
  const sha256=buyerHash(raw),closeSha256=buyerHash(buyerCanonical(close));
  return {document:source,raw,sha256,closeSha256,rows,
    source:{kind:'buyer-expense-period',runId:null,reportSha256:sha256,reportBytes:raw.length,reportSchema:BUYER_SOURCE_SCHEMA,reportCreatedAt:close.created_at,
      periodClose:{id:close.id,revision:close.sequence,sha256:closeSha256,schema:close.schema,period:copy(close.period)},
      buyer:{workspaceId:source.workspaceId,periodId:close.period.id,closeId:close.id,sequence:close.sequence,contextSha256:close.context_sha256,
        dataContext:close.data_context??'operational',review:copy(close.review),totals:copy(close.totals),creditTotals:copy(close.credit_totals??[]),netTotals:copy(close.net_totals??close.totals),
        outstandingReservations:copy(close.outstanding_reservations??[]),sourceCaptures:copy(close.source_captures??[])}}
  };
}

export function createBuyerHandoff({buyerSourceBytes,name,actor,id=randomUUID(),createdAt=new Date().toISOString(),labels=[]}={}){
  const inspected=inspectBuyerSource(buyerSourceBytes);ident(id,'handoff identity');text(name,'handoff name',160);text(actor,'operator',1000);
  check(typeof createdAt==='string'&&/(?:Z|[+-]\d\d:\d\d)$/.test(createdAt)&&Number.isFinite(Date.parse(createdAt)),'INVALID_BUYER_SOURCE','Use a creation timestamp with an explicit time zone.');
  check(Array.isArray(labels)&&labels.length===0,'BUYER_LABELS_RETAINED','Buyer account and allocation labels come from the issued source.');
  const rows=inspected.rows.map(row=>({...row,rowId:rowId(id,inspected.sha256,row.sourceLineId),sourceRowSha256:buyerHash(buyerCanonical(row.original)),
    label:{assetLabel:row.original.asset,unitLabel:'native atomic units',accountCode:row.original.account_code,accountName:''}}));
  const summary={totalRows:rows.length,expenseRows:rows.filter(row=>row.kind==='EXPENSE').length,creditRows:rows.filter(row=>row.kind==='CREDIT').length,
    testnetRows:rows.filter(row=>row.original.network==='stellar:testnet').length,publicNetworkRows:rows.filter(row=>row.original.network==='stellar:pubnet').length,
    dataContext:inspected.source.buyer.dataContext,outstandingReservations:inspected.source.buyer.outstandingReservations.length};
  return seal({schema:BUYER_HANDOFF_SCHEMA,id,name,actor,createdAt,source:inspected.source,
    sourceHashes:{buyerSourceSha256:inspected.sha256,issuedCloseSha256:inspected.closeSha256},sourceAccountingStatus:'ISSUED_BUYER_PERIOD',
    sourceOptions:[],labels:[],rows,summary});
}
export function validateBuyerHandoff(handoff){
  check(isBuyerHandoff(handoff)&&object(handoff.integrity)&&HEX.test(handoff.integrity.sha256),'INVALID_BUYER_HANDOFF','Choose a retained buyer accountant handoff.');
  const {integrity,...body}=handoff;
  check(buyerHash(buyerCanonical(body))===integrity.sha256,'BUYER_HANDOFF_CHANGED','The retained buyer handoff changed.',409);
  ident(handoff.id,'handoff identity');
  check(handoff.source?.kind==='buyer-expense-period'&&object(handoff.source.buyer)&&HEX.test(handoff.source.reportSha256)&&Array.isArray(handoff.rows)&&handoff.rows.length<=22000,'INVALID_BUYER_HANDOFF','Retain the complete typed buyer source identity.');
  ident(handoff.source.buyer.workspaceId,'buyer workspace identity');
  const seen=new Set();
  for(const row of handoff.rows){
    check(object(row)&&['EXPENSE','CREDIT'].includes(row.kind)&&object(row.original)&&object(row.label)&&HEX.test(row.sourceLineId)&&row.sourceLineId===sourceLineId(handoff.source.buyer.workspaceId,row.kind,row.original)&&row.rowId===rowId(handoff.id,handoff.source.reportSha256,row.sourceLineId)&&row.sourceRowSha256===buyerHash(buyerCanonical(row.original)),'BUYER_HANDOFF_ROW_CHANGED','A frozen buyer allocation or identity changed.',409);
    check(!seen.has(row.sourceLineId),'BUYER_LINE_REPEATED','The handoff repeats an original buyer allocation.',409);seen.add(row.sourceLineId);
  }
  return handoff;
}
export function buyerProtectedValues(handoff,row){
  return {...row.original,handoffId:handoff.id,sourceWorkspaceId:handoff.source.buyer.workspaceId,sourceCloseId:handoff.source.buyer.closeId,
    sourceCloseSequence:handoff.source.buyer.sequence,sourceContextSha256:handoff.source.buyer.contextSha256,
    sourceReportSha256:handoff.source.reportSha256,rowId:row.rowId,sourceRowSha256:row.sourceRowSha256,
    allocationKind:row.kind,sourceLineId:row.sourceLineId,assetLabel:row.label.assetLabel,unitLabel:row.label.unitLabel,
    accountCode:row.label.accountCode,accountName:row.label.accountName};
}

/** Original cross-edition allocation/economic identities used by bookkeeping adapters.
 * The existing component namespace is retained byte-for-byte for saved Xero plans. */
export function buyerAccountingComponents(handoff){
  validateBuyerHandoff(handoff);
  const occurrences=new Map();
  return handoff.rows.map(row=>{
    const source=row.original,kind=row.kind==='EXPENSE'?'BUYER_EXPENSE':'BUYER_CREDIT',native=source.native_payment??null;
    const economicId=buyerHash(buyerCanonical({workspaceId:handoff.source.buyer.workspaceId,kind,network:source.network,asset:source.asset,identity:source.transfer_identity??native?.transfer_identity??source.item_id}));
    const dimension=buyerCanonical([economicId,source.center_id,source.project,source.account_code]),occurrence=(occurrences.get(dimension)??0)+1;occurrences.set(dimension,occurrence);
    return {id:buyerHash('stellar-forge.xero-buyer-component.v1\n'+dimension+'\n'+occurrence),kind,rowId:row.rowId,sourceLineId:row.sourceLineId,sourceRowSha256:row.sourceRowSha256,
      economicId,network:source.network,sourceAt:source.recognition_date,sourceTimeBasis:'BUYER_REVIEWED_RECOGNITION_DATE',amountAtomic:source.amount,originalEconomicAmount:row.kind==='CREDIT'?source.native_return:source.settled_actual,
      asset:source.asset,assetLabel:row.label.assetLabel,unitLabel:row.label.unitLabel,transfer:row.kind==='CREDIT'?'TRANSFER_MATCHED':native?.classification??'SF36_FINALIZED_RECEIPT',
      transactionFingerprint:source.transaction??native?.observation?.transactionHash??source.receipt_ref??null,observationSha256:source.observation_sha256??native?.observation_sha256??null,
      dataContext:source.data_context??native?.data_context??handoff.source.buyer.dataContext,costCenter:source.center_code,project:source.project,sourceAccountCode:source.account_code,
      codingId:source.coding_id,line:source.line,itemId:source.item_id,creditId:source.credit_id??null};
  });
}

const html=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderBuyerAccountantHtml(view,revision){
