    '<p>Known merchant USD quotes total '+e(statement.totals.merchantQuotedUsd.knownTotal)+' across '+statement.totals.merchantQuotedUsd.knownOrders+' orders; '+statement.totals.merchantQuotedUsd.unknownOrders+' orders have no quote.</p>'+
    (statement.source.usage?'<p>Service allowance balances are cumulative as of '+e(statement.source.usage.createdAt)+' (source revision '+e(statement.source.usage.revision)+').'+(statement.servicePeriod?' The service activity section compares this closing snapshot to its retained opening snapshot.':' The selected purchase period does not change that usage snapshot.')+'</p>':'')+'</section>'+
    renderServicePeriodHtml(statement.servicePeriod)+orderRows+excluded+'<footer>Original accounting run '+e(statement.source.runId)+'<br>Report SHA-256: <code>'+e(statement.source.reportSha256)+'</code>'+
    (statement.source.usageOpening?'<br>Opening service usage SHA-256: <code>'+e(statement.source.usageOpening.sha256)+'</code>':'')+
    (statement.source.usage?'<br>Service usage SHA-256: <code>'+e(statement.source.usage.sha256)+'</code>':'')+'</footer></main></body></html>\n';
}

// MIT. Project the installed original SF101 API-pass export into customer usage.
const SCHEMA='stellar-forge.sf101.api-pass-export.v1';
const HEX=/^[a-f0-9]{64}$/;
const need=(ok,code,message)=>{if(!ok)throw Object.assign(new Error(message),{code,status:400});};
const object=value=>value&&typeof value==='object'&&!Array.isArray(value);
const count=(value,name,positive=false)=>{
  need(Number.isSafeInteger(value)&&value>=0&&(!positive||value>0),'INVALID_NATIVE_USAGE_INTEGER','Check the original '+name+'.');return value;
};
const digest=(value,name)=>{need(typeof value==='string'&&HEX.test(value),'INVALID_NATIVE_USAGE_DIGEST','Check the original '+name+'.');return value;};
const text=(value,name,max=2048)=>{
  need(typeof value==='string'&&value.length>0&&value.length<=max&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value),
    'INVALID_NATIVE_USAGE_FIELD','Check the original '+name+'.');return value;
};
const time=(value,name)=>{text(value,name,80);need(Number.isFinite(Date.parse(value)),'INVALID_NATIVE_USAGE_TIME','Check the original '+name+'.');return value;};
const statuses=new Set(['IN_FLIGHT','RECOVERY_REQUIRED','COMPLETED','CONSUMED','RELEASED']);
export function projectApiPassExport(value){
  need(object(value)&&value.schema===SCHEMA&&object(value.pass)&&Array.isArray(value.calls)&&value.calls.length<=20000,
    'INVALID_NATIVE_PASS_EXPORT','Import the original complete API-pass export with up to 20,000 calls.');
  const pass=value.pass,native=pass.native,plan=pass.plan,usage=pass.usage;
  need(object(native)&&object(plan)&&plan.schema==='stellar-forge.sf101.api-pass.v1'&&object(usage),
    'INVALID_NATIVE_PASS_EXPORT','The original export must include its pass, native order, purchased plan and durable usage.');
  need(pass.orderRef===native.orderRef,'NATIVE_PASS_ORDER_CHANGED','The exported pass differs from its original native order.');
  const planSha256=digest(pass.planSha256,'plan digest'),manifestSha256=digest(pass.manifestSha256,'purchased manifest digest');
  need(manifestSha256===native.fileSha256,'NATIVE_PASS_MANIFEST_CHANGED','The API pass differs from the original purchased manifest.');
  need(object(value.snapshot)&&Array.isArray(value.actions),'NATIVE_CAPTURE_REQUIRED','Import the original complete API-pass snapshot.');
  const createdAt=value.snapshot.capturedAt,revision=digest(value.snapshot.stateSha256,'durable snapshot identity');
  need(count(value.snapshot.callCount,'snapshot call count')===value.calls.length&&count(value.snapshot.actionCount,'snapshot action count')===value.actions.length,
    'INCOMPLETE_NATIVE_PASS_EXPORT','The captured call and operation counts must match the complete original export.');
  need(typeof createdAt==='string','NATIVE_CAPTURE_TIME_REQUIRED','Export the original API pass with its actual capture timestamp.');
  time(createdAt,'capture timestamp');
  need((typeof revision==='string'&&revision.length>0&&revision.length<=160)||(Number.isSafeInteger(revision)&&revision>=0),
    'NATIVE_CAPTURE_REVISION_REQUIRED','Export the original API pass with its immutable snapshot revision.');

  need(Array.isArray(plan.routes)&&plan.routes.length>0,'NATIVE_PASS_ROUTES_REQUIRED','The purchased plan must retain its original routes.');
  const routes=new Map();
  for(const route of plan.routes){
    need(object(route),'INVALID_NATIVE_PASS_ROUTE','Check the original purchased route.');
    const id=text(route.id,'route ID',160);
    need(!routes.has(id),'DUPLICATE_NATIVE_PASS_ROUTE','The purchased plan repeats a route ID.');
    routes.set(id,{id,method:text(route.method,'route method',10),path:text(route.path,'route path'),units:count(route.units,'route units',true)});
  }
  const seen=new Set(),totals={consumedUnits:0n,reservedUnits:0n,completedCalls:0,consumedCallsWithoutResult:0,reservedCalls:0,releasedCalls:0};
  const calls=value.calls.map(call=>{
    need(object(call)&&call.orderRef===pass.orderRef,'NATIVE_CALL_ORDER_CHANGED','A call is bound to a different original order.');
    const requestId=text(call.requestId,'request ID',160);need(!seen.has(requestId),'DUPLICATE_NATIVE_CALL','The original call export repeats a request ID.');seen.add(requestId);
    const route=routes.get(call.routeId),units=count(call.units,'call units',true);
    need(route&&call.method===route.method&&call.path===route.path&&units===route.units,
      'NATIVE_CALL_PLAN_CHANGED','An original call differs from its immutable purchased route or unit price.');
    need(statuses.has(call.storedStatus)&&statuses.has(call.status),'INVALID_NATIVE_CALL_STATUS','Check the original durable call status.');
    need(call.status===call.storedStatus||(call.storedStatus==='IN_FLIGHT'&&call.status==='RECOVERY_REQUIRED'),
      'NATIVE_CALL_STATUS_CHANGED','The displayed call outcome differs from its durable status.');
    if(['IN_FLIGHT','RECOVERY_REQUIRED'].includes(call.storedStatus)){totals.reservedUnits+=BigInt(units);totals.reservedCalls++;}
    else if(call.storedStatus==='COMPLETED'){totals.consumedUnits+=BigInt(units);totals.completedCalls++;}
    else if(call.storedStatus==='CONSUMED'){totals.consumedUnits+=BigInt(units);totals.consumedCallsWithoutResult++;}
    else totals.releasedCalls++;
    let result=null;
    if(call.result!==null&&call.result!==undefined){
      need(object(call.result)&&Number.isInteger(call.result.status)&&call.result.status>=100&&call.result.status<=599,
        'INVALID_NATIVE_CALL_RESULT','Check the original retained response metadata.');
      result={status:call.result.status,contentType:text(call.result.contentType,'response content type',300),
        sha256:digest(call.result.sha256,'response digest'),bytes:count(call.result.bytes,'response bytes')};
    }
    return {requestId,routeId:call.routeId,method:call.method,path:call.path,requestSha256:digest(call.requestSha256,'request digest'),
      units:String(units),consumedUnits:['COMPLETED','CONSUMED'].includes(call.storedStatus)?String(units):'0',
      reservedUnits:['IN_FLIGHT','RECOVERY_REQUIRED'].includes(call.storedStatus)?String(units):'0',status:call.status,storedStatus:call.storedStatus,revision:count(call.revision,'call revision'),
      startedAt:time(call.startedAt,'call start'),deadlineAt:time(call.deadlineAt,'call deadline'),updatedAt:time(call.updatedAt,'call update'),
      errorCode:call.errorCode===null||call.errorCode===undefined?null:text(call.errorCode,'call outcome code',200),result};
  }).sort((a,b)=>a.startedAt.localeCompare(b.startedAt)||a.requestId.localeCompare(b.requestId));
  const allowance=count(usage.allowanceUnits,'allowance units',true),consumed=count(usage.consumedUnits,'consumed units'),
    reserved=count(usage.reservedUnits,'reserved units'),available=count(usage.availableUnits,'available units');
  need(allowance===count(plan.allowanceUnits,'purchased plan allowance',true),'NATIVE_ALLOWANCE_CHANGED','The durable allowance differs from its purchased plan.');
  need(totals.consumedUnits===BigInt(consumed)&&totals.reservedUnits===BigInt(reserved)&&BigInt(consumed)+BigInt(reserved)+BigInt(available)===BigInt(allowance),
    'INCOMPLETE_NATIVE_CALL_EXPORT','The complete original call history must account for every consumed and reserved unit.');
  for(const name of ['completedCalls','consumedCallsWithoutResult','reservedCalls','releasedCalls']){
    need(totals[name]===count(usage[name],name),'INCOMPLETE_NATIVE_CALL_EXPORT','The complete original call history must match its durable call counts.');
  }
  need(value.nextAfter===undefined||value.nextAfter===null,'INCOMPLETE_NATIVE_CALL_EXPORT','Export all remaining native call pages before importing customer usage.');
  return {usage:{schema:'stellar-forge.sf101.service-usage-export.v1',createdAt,revision,orders:[{
    orderRef:native.orderRef,eventId:native.eventId??null,routeId:native.routeId,method:native.method,network:native.network,
    amountAtomic:native.amountAtomic,assetDigest:native.assetDigest,recipientDigest:native.recipientDigest??null,entitledAt:native.entitledAt??null,
    planId:planSha256,planLabel:plan.title,planRevision:manifestSha256,
    unitsPurchased:String(allowance),unitsUsed:String(consumed),unitsReserved:String(reserved),unitsRemaining:String(available)
  }]},extras:{planSha256,manifestSha256,callsComplete:true,calls}};
}

// MIT. Customer statement operator desk. All displayed values are inserted as text.
const $=id=>document.getElementById(id);
const API='/api/customer-statements';
let state=null,working=false,preview=null,currentDocument=null,pendingRetention=null,bindingsOffset=0,bindingsTotal=0,registerOffset=0,registerTotal=0;
const knownStatements=new Map();
const create=(tag,text,className)=>{
  const element=document.createElement(tag);if(text!==undefined&&text!==null)element.textContent=String(text);if(className)element.className=className;return element;
};
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function actor(){const value=$('operator').value.trim();if(!value)throw new Error('Enter the operator name before saving workspace changes.');try{localStorage.setItem('merchant-customer-statement-operator',value);}catch{}return value;}
function readable(value){return String(value??'Unrecorded').replaceAll('_',' ').toLowerCase();}
function setOptions(element,rows,emptyLabel,selected=element.value){
  element.replaceChildren();
  if(emptyLabel!==null){const option=create('option',emptyLabel);option.value='';element.append(option);}
  for(const row of rows){const option=create('option',row.label);option.value=row.value;element.append(option);}
  if([...element.options].some(option=>option.value===selected))element.value=selected;
}
function availability(){
  document.querySelectorAll('button').forEach(button=>button.disabled=working||button.dataset.rangeDisabled==='true');
  $('assign-button').disabled=working||!$('customer-picker').value;
  $('retain').disabled=working||(!preview&&!pendingRetention);
  $('bindings-prev').disabled=working||bindingsOffset===0;
  $('bindings-next').disabled=working||bindingsOffset+50>=bindingsTotal;
  $('register-prev').disabled=working||registerOffset===0;
  $('register-next').disabled=working||registerOffset+50>=registerTotal;
  $('correct-document').disabled=working||currentDocument?.statement.status!=='RETAINED';
  document.body.classList.toggle('working',working);
  document.body.setAttribute('aria-busy',String(working));
}
async function run(action){
  if(working)return;working=true;availability();
  try{await action();}
  catch(error){status(error.message||'The operation failed.',true);}
  finally{working=false;availability();}
}
async function request(path='',value){
  const response=await fetch(API+path,{method:value===undefined?'GET':'POST',cache:'no-store',
    headers:value===undefined?{}:{'Content-Type':'application/json','X-Workspace-Request':'1'},...(value===undefined?{}:{body:JSON.stringify(value)})});
  let result;
  try{result=await response.json();}catch{throw Object.assign(new Error('The workspace response could not be read. Refresh the register to recover the current document state.'),{uncertain:true});}
  if(!response.ok)throw Object.assign(new Error(result.error?.message??result.message??'The workspace operation failed.'),{code:typeof result.error==='string'?result.error:result.error?.code,status:response.status});
  return result;
}
function clearPreview(){
  preview=null;$('preview-panel').hidden=true;
  if(!pendingRetention){$('retain').textContent='Retain statement';$('retention-note').textContent='Review the original purchases, usage and adjustments before retaining this document.';}
}
function takeState(value){
  state=value;$('revision').textContent='Workspace revision '+state.revision;
  for(const row of state.statements)knownStatements.set(row.id,row);
  const chosen=$('customer-picker').value;
  const customers=state.customers.map(row=>({value:row.id,label:row.reference+' · '+row.name}));
  setOptions($('customer-picker'),customers,'New customer',chosen);
  setOptions($('statement-customer'),customers,'Choose customer');
  setOptions($('register-customer'),customers,'All customers');
  setOptions($('statement-run'),state.runs.map(row=>({value:row.id,label:(row.name??row.id)+' · '+(row.completedAt??row.createdAt??'')})),'Choose completed run');
  setOptions($('statement-usage'),state.usageImports.map(row=>({value:row.id,label:row.name+' · '+row.sourceCreatedAt})),'Purchases only');
  setOptions($('statement-usage-opening'),state.usageImports.filter(row=>row.sourceSchema==='stellar-forge.sf101.api-pass-export.v1')
    .map(row=>({value:row.id,label:row.name+' · '+row.sourceCreatedAt})),'Choose opening snapshot');
  updatePeriodMode();updateCorrections();
  $('metrics').replaceChildren();
  for(const [name,value] of [['Customers',state.customers.length],['Assigned orders',state.bindingCount],['Retained documents',state.statementCount],['Completed accounting runs',state.runs.length]]){
    const card=create('div',null,'metric');card.append(create('span',name),create('strong',value));$('metrics').append(card);
  }
  const latest=state.usageImports[0];$('usage-summary').replaceChildren();
  if(latest){$('usage-summary').append(create('p',latest.name),create('small',latest.orderCount+' original orders · Captured '+latest.sourceCreatedAt),
    create('small','Service revision '+latest.sourceRevision+' · '+state.usageImportCount+' retained captures'));}
  else $('usage-summary').append(create('p','No service usage captures imported.'));
  if(preview&&preview.revision!==state.revision&&!pendingRetention)clearPreview();
}
function fillCustomer(id){
  const row=state.customers.find(row=>row.id===id),form=$('customer-form');
  for(const key of ['reference','name','email','address','note'])form.elements[key].value=row?.[key]??'';
  form.dataset.id=row?.id??'';form.dataset.version=row?.version??'';
  if(row)$('statement-customer').value=row.id;
  updateCorrections();availability();
}
function updateCorrections(){
  const customerId=$('statement-customer').value;
  setOptions($('statement-replaces'),[...knownStatements.values()].filter(row=>row.status==='RETAINED'&&row.customerId===customerId)
    .sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(row=>({value:row.id,label:row.number+' · '+row.createdAt})),'New statement');
}
async function loadBindings(){
  const customerId=$('customer-picker').value;
  const body=$('binding-rows');body.replaceChildren();
  if(!customerId){bindingsOffset=0;bindingsTotal=0;$('binding-count').textContent='';$('bindings-page').textContent='Choose customer';return;}
  const page=await request('/bindings?'+new URLSearchParams({customerId,offset:bindingsOffset,limit:50}));
  bindingsTotal=page.total;
  for(const row of page.items){const tr=create('tr');tr.append(create('td',row.orderRef,'mono'),create('td',row.label||'—'),create('td',row.version));body.append(tr);}
  if(!page.items.length){const td=create('td','No original orders assigned.','empty');td.colSpan=3;const tr=create('tr');tr.append(td);body.append(tr);}
  $('binding-count').textContent=page.total+' orders';
  $('bindings-page').textContent=page.total?String(bindingsOffset+1)+'–'+Math.min(bindingsOffset+50,page.total)+' of '+page.total:'0 orders';
}
async function loadRegister(){
  const query={offset:registerOffset,limit:50};
  if($('register-customer').value)query.customerId=$('register-customer').value;
  if($('register-status').value)query.status=$('register-status').value;
  const page=await request('/statements?'+new URLSearchParams(query));registerTotal=page.total;
  const body=$('register-rows');body.replaceChildren();
  for(const row of page.items){
    knownStatements.set(row.id,row);const tr=create('tr'),number=create('td',row.number),person=create('td',row.customerName);
    if(row.servicePeriod)number.append(create('small','Service '+row.servicePeriod.from+' to '+row.servicePeriod.until));
    person.append(create('small',row.customerReference));const stateCell=create('td');stateCell.append(create('span',row.status,'badge'));
    const open=create('button','Open');open.type='button';open.addEventListener('click',()=>run(()=>openDocument(row.id)));const action=create('td');action.append(open);
    tr.append(number,person,create('td',row.createdAt),create('td',row.orderCount,'numeric'),stateCell,action);body.append(tr);
  }
  if(!page.items.length){const td=create('td','No retained statements match this selection.','empty');td.colSpan=6;const tr=create('tr');tr.append(td);body.append(tr);}
  $('register-page').textContent=page.total?String(registerOffset+1)+'–'+Math.min(registerOffset+50,page.total)+' of '+page.total:'0 documents';
  updateCorrections();
}
async function refresh(){
  takeState(await request());await loadBindings();await loadRegister();
  status('Workspace revision '+state.revision+' loaded.');
}
function addDefinition(dl,name,value,mono=false){dl.append(create('dt',name),create('dd',value,mono?'mono':null));}
function assetsTable(documentValue){
  const table=create('table'),head=create('thead'),tr=create('tr');
  for(const title of ['Network / asset / recipient','Orders','Original atomic amount','Officially matched','Verified refunds','Pending refunds'])tr.append(create('th',title));
  head.append(tr);table.append(head);const body=create('tbody');
  for(const row of documentValue.totals.byAsset){
    const tr=create('tr'),asset=create('td',row.network);
    asset.append(create('small','Asset '+row.assetDigest,'mono'),create('small','Recipient '+(row.recipientDigest??'unrecorded'),'mono'));tr.append(asset);
    for(const key of ['orders','reportedAmountAtomic','officialMatchedAmountAtomic','refundedAmountAtomic','pendingRefundAmountAtomic'])tr.append(create('td',row[key],'numeric'));
    body.append(tr);
  }
  table.append(body);const wrap=create('div',null,'table-wrap');wrap.append(table);return wrap;
}
const exclusionNames={
  ORDER_NOT_IN_SELECTED_REPORT:'Assigned order absent from the selected report or recorded date range.',
  AMBIGUOUS_ORDER_EVENTS:'Several original events use this assigned order reference.',
  SERVICE_PAYMENT_IDENTITY_MISMATCH:'The service usage snapshot differs from the original order, event or payment terms.',
  ORIGINAL_NATIVE_ORDER_REQUIRED:'The original native checkout capture is required for this order.'
