  const quotes=value.totals.merchantQuotedUsd;
  target.append(create('p','Known merchant USD quotes: '+quotes.knownTotal+' across '+quotes.knownOrders+' orders. '+quotes.unknownOrders+' orders have no recorded quote.','muted'));
