  cancel(id: string, value: CancelPaymentRequestInput): Promise<PaymentRequestMutationResult>;
  reportReturn(id: string, value: ReturnedPaymentInput): Promise<PaymentRequestMutationResult & {paymentReturn: PaymentReturn}>;
