        for (const field of ['at', 'action', 'causeCode']) if (typeof error.commitUncertainty[field] === 'string') selected[field] = error.commitUncertainty[field];
        if (Number.isSafeInteger(error.commitUncertainty.revision)) selected.revision = error.commitUncertainty.revision;
        recovery.commitUncertainty = selected;
      }
      if (Object.keys(recovery).length) { Object.assign(exposed, recovery); exposed.details = recovery; }
      else if (plain(error.details)) exposed.details = this.#safe(error.details);
      if (Number.isInteger(error.status) && error.status >= 400 && error.status <= 599) exposed.status = error.status;
      throw exposed;
    }
  }
  close() {
    if (!this.#close) {
      this.#closing = true;
      const attempt = (async () => {
        // Accepted coordinator calls may still admit children. Drain them before
        // taking the final set of original owners to close.
        for (;;) {
          const records = [...this.#sessions.values()];
          await Promise.allSettled(records.flatMap(record => [record.opening, ...record.calls].filter(Boolean)));
          if ([...this.#sessions.values()].every(record => record.calls.size === 0)) break;
        }
        const results = await Promise.allSettled([...this.#sessions.keys()].map(key => this.#closeWorkspace(key)));
        await Promise.allSettled([...this.#sourcePreviews]);
        const rejected = results.find(result => result.status === 'rejected');
        if (rejected) throw rejected.reason;
        await this.#files.close();
      })();
      this.#close = attempt;
      attempt.catch(() => { if (this.#close === attempt) this.#close = null; });
